      '新建两个概念和一个模型。前置征缴讲税按设立时的标准先足额收走、不等收益兑现，要害在时点不在税率；避风港反转讲一个法域的信息屏障补齐之后，藏资产的地方反而成了处置最顺手的地方；组合穿透讲几条各自能绕过去的监管线同时落下就没有出口，而穿透的产出是一份可排序的底账。瑕疵资产击穿、财富回收挤压和资产保全架构三个既有节点回填了本期。',
      '新建五个关键词词条，分别是储蓄型保险、离岸信托、CRS、滞纳金、香港国安法，后两个配了可核对的官方来源。香港保险这个旧词条原来只有一段泛泛的介绍、连 kind 都没有、episodes 是空的，这次按产品类补写成完整词条并接上 EP010 和本期。富途、高净值人群、离岸财富、家族办公室、香港、资本管制、保险七个已有词条补上了本期并补了相关词链接。',
      '延展串了六期旧节目。EP185 和 EP156 是香港这条线更早的两段，钱挪过去换的只是棋盘；EP010 的许家印信托被击穿和 EP188 的新加坡家族办公室合起来解释了国内这批信托为什么脱不了身；EP121 的潘石屹提前离场对上节目那句真正做完的人 2017 到 2019 年就收了手；EP194 的五年期存单只给 1.6，和万分之五一天的滞纳金摆在一起才看得出钱在哪一头缩得快。'
