      'B 站一直没有给 8 月 5 日那场生成 AI 字幕轨，只有弹幕轨，所以这一期的转写稿是本地 whisper 转出来的，106 分钟音频转出 3018 行。第一次下的音频是坏的，视频 106 分钟，转出来的文件只有 7.7 分钟，yt-dlp 却报成功，靠比对时长才发现。',
