      '为转录建了一张校正表，放在 scripts/transcript-terms.json，配 scripts/apply-transcript-terms.py，写法见 sop/09。三层结构：全库统一的术语替换、按期号生效的精修、以及只用来读懂稿子绝不替换进正文的讳称对照。跑 LIVE030 改了 151 处，全库扫下来最常错的是讳称和人名，朗朗被写成郎朗或者狼狼，小乌被写成小屋或者小吴，长坡漫道有七种错法。',
