      '六组大话题按现场顺序排。美伊那边换谁上来都行，只要控制权、不搞核、停灰色贸易这三件对得上；欧洲被六万人游过飞地的移民事件和贸易逆差逼着抱团；霍尔木兹再封油价也跳不起来，因为钱会自己去挖运河、铺管道；中产是长江边上的蓄水池，主河道水位一降先抽的就是它。落点在信托和保险，能不能挡住看这笔钱有没有真的离开你。',
      '十五个标签全部命中关键词库，这次没有新建词条，全部复用香港保险、家族办公室、离岸财富、中产阶级、灰色贸易、霍尔木兹海峡、马六甲海峡这些既有词。',
