      'EP196 上线，入口是韩红基金会传出接受调查。节目直说这件事真假无从查证，要问的是这种基金模式本身。捐款来自千千万万普通人，钱汇上去之后受益方变成一个个机构、一个个合作方，最该被救的人反而漏掉了。B 站是会员专属，YouTube 同日已发布，两条视频链接都齐。',
      '五条核心观点分别落在制度门槛、治理选择、权责结构、监督链条和救助覆盖。最硬的一处是法律从没禁止公募机构救助个人，规范只要求捐款不能限定唯一受益人，所以不在服务范围内这个说法是借口不是规则。另一处是资金拨出去之后落地、筛选、追责全归合作方，连合规文件也由合作方自己出。',
