      '新建六个关键词词条，分别是公募资格、个人求助、机构对接、圈层利益、懒政、民间求助平台。韩红这个已有词条补上了本期，并加了一组节目关联，说明她在 EP172 是被借用公信力的人，在这一期是话题入口。',
