      'EP194 上线，讲工农中建四大行把停发近半年的五年期大额存单重新上架。三年期 1.5%、五年期 1.6%，多存两年只多五个基点，节目由此判断银行预判的是利率长期下行，不是市面解读的加息在即。B 站是会员专属，YouTube 当天尚未发布，视频链接因此只有一条。',
